import SwiftUI
import AVKit
import UniformTypeIdentifiers
import Security
import Combine

// DuoCinema V1.8 — right-aligned responsive controls, retaining WebDAV and cinema visuals.
// Keep the @main App file generated by Xcode.
struct ContentView: View {
    @State private var player = AVPlayer()
    @State private var currentTitle = "私人影院"
    @State private var inputURL = ""
    @State private var showURLSheet = false
    @State private var showImporter = false
    @State private var showLibrary = false
    @State private var showWebDAV = false
    @State private var remoteDownloadActive = false
    @State private var isMuted = false
    @State private var playbackError: String?
    @State private var scopedURL: URL?
    @State private var isSeeking = false
    @State private var scrubTime = 0.0
    @State private var playing = false
    @State private var controlsVisible = true
    @State private var immersiveFullScreen = false
    @State private var playbackRate: Float = 1
    // nil: adaptive automatic framing. true: force Fill. false: force Fit.
    @State private var framingOverride: Bool? = nil
    @State private var foldRegion: CGRect? = nil
    @State private var systemInsets: UIEdgeInsets = .zero
    @State private var observedVideoSize: CGSize = .zero
    @Environment(\.horizontalSizeClass) private var widthClass

    // The NavigationStack owns the toolbars. On iPhone Duo, iOS places them
    // vertically with the real status bar / camera avoidance region.
    // Never position custom actions over the system status indicators.
    var body: some View {
        NavigationStack {
            playerCanvas
                // The black cinema canvas bleeds beneath system status/side
                // toolbars. Only interactive controls respect safe insets.
                .ignoresSafeArea(.container, edges: .all)
                .navigationBarTitleDisplayMode(.inline)
                .toolbarBackground(.hidden, for: .navigationBar)
                .toolbar(immersiveFullScreen ? .hidden : .visible, for: .navigationBar)
                .toolbar {
                    if !immersiveFullScreen {
                        ToolbarItem(placement: .topBarLeading) {
                            Button {
                                showLibrary = true
                            } label: {
                                Label("媒体库", systemImage: "square.stack")
                            }
                            .accessibilityLabel("打开媒体库")
                        }
                        ToolbarItemGroup(placement: .topBarTrailing) {
                            Button {
                                // The auto default is crop-to-fill on wide panes,
                                // and show-complete-frame on narrow panes.
                                framingOverride = !(framingOverride ?? defaultFill)
                            } label: {
                                Label("切换画面比例", systemImage: "arrow.up.left.and.arrow.down.right")
                            }
                            Button {
                                withAnimation(.easeInOut(duration: 0.2)) {
                                    controlsVisible.toggle()
                                }
                            } label: {
                                Label("显示或隐藏控制台", systemImage: "slider.horizontal.3")
                            }
                        }
                    }
                }
        }
        // Keep the navigation rail transparent over a uniform black canvas;
        // the status bar icons and tap targets remain owned by iOS.
        .background { immersiveBackdrop.ignoresSafeArea() }
        .background {
            SystemInsetsReader(insets: $systemInsets)
                .allowsHitTesting(false)
                .ignoresSafeArea()
        }
        // Leave the status bar to iOS. Only an explicit Full Screen tap hides it.
        .statusBarHidden(immersiveFullScreen)
        .preferredColorScheme(.dark)
        .sheet(isPresented: $showLibrary) { sourceSheet }
        .sheet(isPresented: $showWebDAV) {
            WebDAVLibraryView { localURL, title in
                showWebDAV = false
                load(localURL, title: title)
            }
        }
        .sheet(isPresented: $showURLSheet) { urlSheet }
        .fileImporter(isPresented: $showImporter,
                      allowedContentTypes: [.movie, .video, .mpeg4Movie, .audio],
                      allowsMultipleSelection: false) { result in
            switch result {
            case .success(let urls):
                if let url = urls.first { openFile(url) }
            case .failure(let error):
                playbackError = error.localizedDescription
            }
        }
        .alert("无法播放", isPresented: Binding(
            get: { playbackError != nil },
            set: { if !$0 { playbackError = nil } }
        )) {
            Button("好", role: .cancel) { playbackError = nil }
        } message: {
            Text(playbackError ?? "")
        }
        .task(id: currentTitle) {
            // AVPlayerItem.presentationSize can arrive after the video starts.
            // Size the foreground layer to the actual video aspect ratio in
            // Fit mode; unused canvas stays clean black.
            for _ in 0..<40 {
                if Task.isCancelled { return }
                if let item = player.currentItem {
                    let natural = item.presentationSize
                    if natural.width > 0, natural.height > 0 {
                        observedVideoSize = natural
                        return
                    }
                }
                try? await Task.sleep(nanoseconds: 250_000_000)
            }
        }
        .onDisappear {
            player.pause()
            scopedURL?.stopAccessingSecurityScopedResource()
        }
    }

    private var defaultFill: Bool {
        let width = displaySize.width
        let height = displaySize.height
        return width > height * 1.30
    }

    @State private var displaySize: CGSize = .zero

    private var playerCanvas: some View {
        GeometryReader { geometry in
            let size = geometry.size
            // Real fold data must be validated against the CURRENT scene bounds.
            // A region left over from an old orientation/outer screen must not
            // force a two-pane layout on a newly rotated single display.
            let hinge = validatedFoldRegion(foldRegion, in: size)
            let horizontal = hinge != nil && hinge!.width > hinge!.height * 1.6
            let vertical = hinge != nil && hinge!.height > hinge!.width * 1.6

            ZStack {
                if immersiveFullScreen {
                    // Actual full-screen mode: the entire screen is movie.
                    videoPane
                } else if horizontal, let hinge {
                    VStack(spacing: 0) {
                        videoPane
                            .frame(height: max(0, min(size.height, hinge.minY)))
                        hingeFill.frame(height: hinge.height)
                        consolePane(showReflection: true,
                                    sourceExtent: max(0, hinge.minY),
                                    horizontalFold: true)
                            .frame(maxWidth: .infinity, maxHeight: .infinity)
                    }
                } else if vertical, let hinge {
                    HStack(spacing: 0) {
                        videoPane
                            .frame(width: max(0, min(size.width, hinge.minX)))
                        hingeFill.frame(width: hinge.width)
                        consolePane(showReflection: true,
                                    sourceExtent: max(0, hinge.minX),
                                    horizontalFold: false)
                            .frame(maxWidth: .infinity, maxHeight: .infinity)
                    }
                } else {
                    // Outer or fully unfolded inner display.
                    videoPane
                    if controlsVisible && !immersiveFullScreen && player.currentItem != nil {
                        VStack(spacing: 0) {
                            Spacer(minLength: 0)
                            compactEdgeControls
                        }
                        .transition(.opacity)
                    }
                }
            }
            .frame(width: size.width, height: size.height)
            .clipped()
            // The full-bleed canvas extends beneath the status/side toolbars.
            // Foreground interactive buttons use their safe-inset padding.
            .background {
                immersiveBackdrop.ignoresSafeArea()
            }
            .background {
                if #available(iOS 27.1, *) {
                    DuoFoldRegionReader(region: $foldRegion)
                        .allowsHitTesting(false)
                }
            }
            .onAppear { displaySize = size }
            .onChange(of: size) { _, newSize in
                displaySize = newSize
                // Discard stale hinge data on physical/scene rotation.
                foldRegion = nil
            }
            .onReceive(NotificationCenter.default.publisher(for: UIDevice.orientationDidChangeNotification)) { _ in
                foldRegion = nil
            }
        }
        // This canvas is full-bleed; toolbar buttons are system-managed and
        // console buttons receive their own safe-area padding below.
    }

    private func validatedFoldRegion(_ candidate: CGRect?, in size: CGSize) -> CGRect? {
        guard let rect = candidate,
              size.width > 100, size.height > 100,
              rect.width > 0, rect.height > 0,
              rect.minX.isFinite, rect.minY.isFinite,
              rect.maxX.isFinite, rect.maxY.isFinite else { return nil }

        let area = CGRect(origin: .zero, size: size)
        let clipped = rect.intersection(area)
        guard !clipped.isNull, !clipped.isEmpty else { return nil }

        if clipped.width >= size.width * 0.70,
           clipped.height <= size.height * 0.18,
           clipped.midY > size.height * 0.15,
           clipped.midY < size.height * 0.85 {
            return clipped
        }
        if clipped.height >= size.height * 0.70,
           clipped.width <= size.width * 0.18,
           clipped.midX > size.width * 0.15,
           clipped.midX < size.width * 0.85 {
            return clipped
        }
        return nil
    }

    // Authentic cinema background: no duplicated, magnified or blurred video
    // is rendered behind the movie. Fit mode preserves the complete frame;
    // unused display space remains uniform black by design.
    private var immersiveBackdrop: some View {
        Color.black
            .allowsHitTesting(false)
    }

    // Keep the division dark and visually continuous; no blurred light band.
    private var hingeFill: some View {
        Color(red: 0.012, green: 0.013, blue: 0.019)
            .accessibilityHidden(true)
    }

    // When the device is flat/unfolded, line up the control panel's TRAILING
    // edge with the floating system toolbar rail. Unlike the old symmetric
    // safe-area padding, the panel does not stop short of the toolbar column.
    // Narrow panes get the available width; wide panes get a smaller deck to
    // reveal more of the movie. The navigation rail is owned by the system.
    private var compactEdgeControls: some View {
        GeometryReader { geo in
            let wide = geo.size.width > geo.size.height * 1.12
            let edge: CGFloat = wide ? 20 : 14
            let width = wide
                ? min(geo.size.width - edge * 2, max(390, geo.size.width * 0.76))
                : max(0, geo.size.width - edge * 2)

            VStack {
                Spacer(minLength: 0)
                HStack(spacing: 0) {
                    Spacer(minLength: 0)
                    controlPanel(compact: wide)
                        .frame(width: max(0, width))
                }
                .padding(.trailing, edge)
                .padding(.bottom, max(wide ? 15 : 18, systemInsets.bottom + 8))
            }
            .frame(width: geo.size.width, height: geo.size.height)
        }
    }

    // In tall panes, preserve the FULL composition with clean black bars.
    // Wide cinema panes can crop to fill by default.
    private var videoPane: some View {
        GeometryReader { pane in
            let fill = framingOverride ?? (pane.size.width > pane.size.height * 1.30)
            let fitSize = aspectFitSize(in: pane.size)
            ZStack {
                // Uniform black letterbox area, without an artificial blurred
                // enlarged copy of the film in the background.
                immersiveBackdrop
                if player.currentItem != nil {
                    if fill {
                        CinemaVideoSurface(player: player, gravity: .resizeAspectFill)
                            .frame(width: pane.size.width, height: pane.size.height)
                    } else {
                        // Fit the video LAYER, not just its content. A full-size
                        // resizeAspect layer would paint opaque BLACK letterboxes.
                        CinemaVideoSurface(player: player, gravity: .resizeAspect)
                            .frame(width: fitSize.width, height: fitSize.height)
                    }
                } else {
                    emptyState
                        .padding(.leading, max(20, systemInsets.left))
                        .padding(.trailing, max(20, systemInsets.right))
                }
            }
            .frame(width: pane.size.width, height: pane.size.height)
            .clipped()
            .contentShape(Rectangle())
            .onTapGesture {
                withAnimation(.easeInOut(duration: 0.2)) {
                    if immersiveFullScreen {
                        immersiveFullScreen = false
                        controlsVisible = true
                    } else {
                        controlsVisible.toggle()
                    }
                }
            }
        }
    }

    private func aspectFitSize(in available: CGSize) -> CGSize {
        let native = observedVideoSize
        let ratio: CGFloat = (native.width > 0 && native.height > 0)
            ? native.width / native.height : (16.0 / 9.0)
        guard available.width > 0, available.height > 0 else { return .zero }
        let width = min(available.width, available.height * ratio)
        return CGSize(width: width, height: width / ratio)
    }

    // The full lower display is the console. There is intentionally no
    // floating card, width cap, opaque side rail or black margin.
    private func consolePane(showReflection: Bool, sourceExtent: CGFloat, horizontalFold: Bool) -> some View {
        GeometryReader { geo in
            ZStack {
                // Dark, neutral base prevents a bright seam at the hinge.
                Color(red: 0.020, green: 0.021, blue: 0.028)
                if showReflection && player.currentItem != nil {
                    // Same source dimensions and crop as the movie pane.
                    // Flip in screen space: the movie's BOTTOM becomes the
                    // reflection's TOP, as in an actual mirror at the hinge.
                    GeometryReader { reflectionGeometry in
                        CinemaVideoSurface(
                            player: player,
                            gravity: (framingOverride ?? ((horizontalFold ? reflectionGeometry.size.width : sourceExtent) >
                                                     (horizontalFold ? sourceExtent : reflectionGeometry.size.height) * 1.30))
                                     ? .resizeAspectFill : .resizeAspect
                        )
                            .frame(width: horizontalFold ? reflectionGeometry.size.width : sourceExtent,
                                   height: horizontalFold ? sourceExtent : reflectionGeometry.size.height)
                            .scaleEffect(x: horizontalFold ? 1 : -1,
                                         y: horizontalFold ? -1 : 1,
                                         anchor: .center)
                            .frame(width: reflectionGeometry.size.width,
                                   height: reflectionGeometry.size.height,
                                   alignment: .topLeading)
                            .clipped()
                            .opacity(0.30)
                            .mask {
                                if horizontalFold {
                                    LinearGradient(stops: [
                                        .init(color: .white.opacity(0.62), location: 0),
                                        .init(color: .white.opacity(0.21), location: 0.22),
                                        .init(color: .clear, location: 0.66)
                                    ], startPoint: .top, endPoint: .bottom)
                                } else {
                                    LinearGradient(stops: [
                                        .init(color: .white.opacity(0.62), location: 0),
                                        .init(color: .white.opacity(0.21), location: 0.22),
                                        .init(color: .clear, location: 0.66)
                                    ], startPoint: .leading, endPoint: .trailing)
                                }
                            }
                    }
                    .allowsHitTesting(false)
                }
                // Small near-hinge darkening instead of a broad opaque blur.
                (horizontalFold ?
                    LinearGradient(colors: [.black.opacity(0.25), .clear], startPoint: .top, endPoint: .bottom) :
                    LinearGradient(colors: [.black.opacity(0.25), .clear], startPoint: .leading, endPoint: .trailing))
                    .allowsHitTesting(false)
                if controlsVisible {
                    expandedControlDeck(
                        height: geo.size.height,
                        sideBySide: !horizontalFold
                    )
                    .transition(.opacity)
                } else if !immersiveFullScreen {
                    VStack {
                        Spacer()
                        Button {
                            withAnimation(.easeInOut(duration: 0.2)) { controlsVisible = true }
                        } label: {
                            Label("显示控制台", systemImage: "slider.horizontal.3")
                                .font(.subheadline.weight(.medium))
                                .padding(.horizontal, 20).padding(.vertical, 12)
                        }
                        .buttonStyle(.plain)
                        .background(.ultraThinMaterial, in: Capsule())
                        .padding(.bottom, 24)
                    }
                }
            }
            .frame(width: geo.size.width, height: geo.size.height)
            .clipped()
        }
    }

    // Half-screen dashboard: controls are spread through the entire bottom
    // pane. A translucent backdrop lets moving video colors shine through.
    private func expandedControlDeck(height: CGFloat, sideBySide: Bool) -> some View {
        let compact = height < 290
        return VStack(spacing: compact ? 10 : 17) {
            HStack(spacing: 13) {
                Image(systemName: "film.stack.fill")
                    .foregroundStyle(.cyan)
                    .font(.system(size: 24))
                    .frame(width: 46, height: 46)
                    .background(.white.opacity(0.09), in: RoundedRectangle(cornerRadius: 13))
                VStack(alignment: .leading, spacing: 4) {
                    Text(currentTitle).font(.system(size: 16, weight: .semibold)).lineLimit(1)
                    Text("DUOCINEMA · NOW PLAYING")
                        .font(.system(size: 10, design: .monospaced))
                        .foregroundStyle(.white.opacity(0.53))
                }
                Spacer(minLength: 4)
                Button { showLibrary = true } label: { Image(systemName: "square.stack.fill") }
                Button { isMuted.toggle(); player.isMuted = isMuted } label: {
                    Image(systemName: isMuted ? "speaker.slash.fill" : "speaker.wave.2.fill")
                }
            }
            .font(.system(size: 19))
            // The side-by-side Duo status/toolbar rail occupies the top-right
            // corner; reserve breathing room for it only in this header.
            .padding(.trailing, sideBySide ? 62 : 0)

            Spacer(minLength: 0)

            HStack(spacing: 12) {
                Button { seek(by: -10) } label: {
                    Image(systemName: "gobackward.10")
                        .frame(maxWidth: .infinity, minHeight: compact ? 54 : 78)
                }
                Button { togglePlayback() } label: {
                    Image(systemName: playing ? "pause.fill" : "play.fill")
                        .font(.system(size: compact ? 30 : 38, weight: .medium))
                        .frame(maxWidth: .infinity, minHeight: compact ? 54 : 78)
                }
                Button { seek(by: 10) } label: {
                    Image(systemName: "goforward.10")
                        .frame(maxWidth: .infinity, minHeight: compact ? 54 : 78)
                }
            }
            .font(.system(size: 27))
            .buttonStyle(DeckButtonStyle())

            Spacer(minLength: 0)

            TimelineView(.periodic(from: .now, by: 0.35)) { _ in
                let duration = validDuration
                let current = isSeeking ? scrubTime : safeCurrentTime
                VStack(spacing: 7) {
                    Slider(value: Binding(
                        get: { min(current, max(duration, 1)) },
                        set: { value in isSeeking = true; scrubTime = value }
                    ), in: 0...max(duration, 1), onEditingChanged: { editing in
                        if !editing {
                            player.seek(to: CMTime(seconds: scrubTime, preferredTimescale: 600))
                            isSeeking = false
                        }
                    })
                    .tint(.white)
                    .disabled(duration <= 0)
                    HStack {
                        Text(formatTime(current))
                        Spacer()
                        Text(duration > 0 ? "-" + formatTime(max(0, duration - current)) : "--:--")
                    }
                    .font(.system(size: 11, design: .monospaced))
                    .foregroundStyle(.white.opacity(0.64))
                }
            }

            HStack(spacing: 10) {
                Button {
                    let next: Float = playbackRate >= 2 ? 1 : (playbackRate == 1 ? 1.25 : (playbackRate == 1.25 ? 1.5 : 2))
                    playbackRate = next
                    if playing { player.rate = next }
                } label: {
                    Label(String(format: "%.2g×", playbackRate), systemImage: "speedometer")
                        .frame(maxWidth: .infinity, minHeight: compact ? 40 : 52)
                }
                Button { showLibrary = true } label: {
                    Label("片库", systemImage: "square.grid.2x2")
                        .frame(maxWidth: .infinity, minHeight: compact ? 40 : 52)
                }
                Button {
                    withAnimation(.easeInOut(duration: 0.2)) {
                        immersiveFullScreen = true
                        controlsVisible = false
                    }
                } label: {
                    Label("全屏", systemImage: "arrow.up.left.and.arrow.down.right")
                        .frame(maxWidth: .infinity, minHeight: compact ? 40 : 52)
                }
            }
            .font(.system(size: 13, weight: .medium))
            .buttonStyle(DeckButtonStyle())
        }
        .buttonStyle(.plain)
        .foregroundStyle(.white)
        // Keep the whole half-screen pane; align its content to the same
        // trailing design grid used by the floating system rail.
        .padding(.leading, sideBySide ? 18 : 20)
        .padding(.trailing, sideBySide ? 18 : 20)
        .padding(.top, compact ? 14 : 24)
        .padding(.bottom, compact ? 16 : 24)
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .background(Color.white.opacity(0.035))
    }

    private var emptyState: some View {
        VStack(spacing: 16) {
            Image(systemName: "play.rectangle.fill")
                .font(.system(size: 52, weight: .ultraLight))
                .foregroundStyle(.cyan)
            Text("DuoCinema")
                .font(.system(size: 32, weight: .semibold, design: .rounded))
            Text("上屏影院 · 下屏控制台")
                .foregroundStyle(.white.opacity(0.55))
                .font(.footnote)
            Button {
                showLibrary = true
            } label: {
                Label("打开影片", systemImage: "folder")
                    .padding(.horizontal, 14)
                    .padding(.vertical, 8)
            }
            .buttonStyle(.borderedProminent)
            .tint(.cyan)
        }
        .foregroundStyle(.white)
    }

    private func controlPanel(compact: Bool) -> some View {
        VStack(spacing: compact ? 9 : 13) {
            HStack(spacing: 12) {
                Image(systemName: "film.stack")
                    .foregroundStyle(.cyan)
                    .frame(width: compact ? 30 : 34, height: compact ? 30 : 34)
                    .background(.white.opacity(0.08), in: RoundedRectangle(cornerRadius: 8))
                VStack(alignment: .leading, spacing: 2) {
                    Text(currentTitle).font(.system(size: 13, weight: .semibold))
                        .lineLimit(1)
                    Text("DUOCINEMA  ·  NOW PLAYING")
                        .font(.system(size: 9, weight: .medium, design: .monospaced))
                        .foregroundStyle(.white.opacity(0.45))
                }
                Spacer(minLength: 3)
                Button { showLibrary = true } label: {
                    Image(systemName: "square.stack")
                }.accessibilityLabel("媒体库")
                Button { isMuted.toggle(); player.isMuted = isMuted } label: {
                    Image(systemName: isMuted ? "speaker.slash.fill" : "speaker.wave.2.fill")
                }.accessibilityLabel(isMuted ? "取消静音" : "静音")
            }

            HStack(spacing: 13) {
                Button { seek(by: -10) } label: {
                    Image(systemName: "gobackward.10")
                        .frame(maxWidth: .infinity, minHeight: compact ? 44 : 54)
                }
                Button { togglePlayback() } label: {
                    Image(systemName: playing ? "pause.fill" : "play.fill")
                        .font(.system(size: compact ? 23 : 27, weight: .semibold))
                        .frame(maxWidth: .infinity, minHeight: compact ? 44 : 54)
                }
                Button { seek(by: 10) } label: {
                    Image(systemName: "goforward.10")
                        .frame(maxWidth: .infinity, minHeight: compact ? 44 : 54)
                }
            }
            .font(.system(size: compact ? 20 : 23, weight: .regular))
            .buttonStyle(DeckButtonStyle())

            // Periodically read the player's playback time without creating
            // a permanent observer or retaining the view model.
            TimelineView(.periodic(from: .now, by: 0.35)) { _ in
                let duration = validDuration
                let current = isSeeking ? scrubTime : safeCurrentTime
                VStack(spacing: 5) {
                    Slider(value: Binding(
                        get: { min(current, max(duration, 1)) },
                        set: { value in
                            isSeeking = true
                            scrubTime = value
                        }
                    ), in: 0...max(duration, 1), onEditingChanged: { editing in
                        if !editing {
                            let seconds = scrubTime
                            player.seek(to: CMTime(seconds: seconds, preferredTimescale: 600))
                            isSeeking = false
                        }
                    })
                    .tint(.white)
                    .disabled(duration <= 0)
                    HStack {
                        Text(formatTime(current))
                        Spacer()
                        Text(duration > 0 ? "-"+formatTime(max(0, duration-current)) : "--:--")
                    }
                    .font(.system(size: 10, weight: .medium, design: .monospaced))
                    .foregroundStyle(.white.opacity(0.6))
                }
            }

            HStack(spacing: 10) {
                Button {
                    let next: Float = playbackRate >= 2 ? 1 : (playbackRate == 1 ? 1.25 : (playbackRate == 1.25 ? 1.5 : 2))
                    playbackRate = next
                    if playing { player.rate = next }
                } label: {
                    Label(String(format: "%.2g×", playbackRate), systemImage: "speedometer")
                        .frame(maxWidth: .infinity, minHeight: compact ? 29 : 36)
                }
                Button { showLibrary = true } label: {
                    Label("片库", systemImage: "square.grid.2x2")
                        .frame(maxWidth: .infinity, minHeight: compact ? 29 : 36)
                }
                Button {
                    withAnimation(.easeInOut(duration: 0.2)) {
                        immersiveFullScreen = true
                        controlsVisible = false
                    }
                } label: {
                    Label("全屏", systemImage: "arrow.up.left.and.arrow.down.right")
                        .frame(maxWidth: .infinity, minHeight: compact ? 29 : 36)
                }
            }
            .font(.system(size: 12, weight: .medium))
            .buttonStyle(DeckButtonStyle())
        }
        .buttonStyle(.plain)
        .foregroundStyle(.white)
        .padding(compact ? 12 : 14)
        .background(.ultraThinMaterial, in: RoundedRectangle(cornerRadius: 22, style: .continuous))
        .overlay {
            RoundedRectangle(cornerRadius: 22, style: .continuous)
                .strokeBorder(.white.opacity(0.15), lineWidth: 0.75)
        }
    }

    private var validDuration: Double {
        guard let item = player.currentItem else { return 0 }
        let duration = CMTimeGetSeconds(item.duration)
        return duration.isFinite && duration > 0 ? duration : 0
    }

    private var safeCurrentTime: Double {
        let seconds = CMTimeGetSeconds(player.currentTime())
        return seconds.isFinite ? max(0, seconds) : 0
    }

    private func formatTime(_ raw: Double) -> String {
        let seconds = Int(max(0, raw.isFinite ? raw : 0))
        let mins = seconds / 60
        let hours = mins / 60
        if hours > 0 {
            return String(format: "%d:%02d:%02d", hours, mins % 60, seconds % 60)
        }
        return String(format: "%02d:%02d", mins, seconds % 60)
    }

    private var sourceSheet: some View {
        NavigationStack {
            List {
                Section("开始播放") {
                    Button {
                        showLibrary = false
                        DispatchQueue.main.asyncAfter(deadline: .now() + 0.35) { showImporter = true }
                    } label: {
                        Label("打开文件 App / 本地影片", systemImage: "folder")
                    }
                    Button {
                        showLibrary = false
                        DispatchQueue.main.asyncAfter(deadline: .now() + 0.35) { showURLSheet = true }
                    } label: {
                        Label("播放 HTTPS 视频直链", systemImage: "link")
                    }
                }
                Section("云盘与 NAS") {
                    Button {
                        showLibrary = false
                        DispatchQueue.main.asyncAfter(deadline: .now() + 0.35) { showWebDAV = true }
                    } label: {
                        Label("我的云盘挂载 / WebDAV", systemImage: "externaldrive.connected.to.line.below")
                    }
                }
                Section("说明") {
                    Text("WebDAV 支持保存多个连接并浏览影片；iCloud Drive、已接入文件 App 的第三方云盘与 SMB 共享可从上方“打开文件 App”访问。")
                    Text("WebDAV 影片在完成缓存下载后播放；暂不支持远程即时拖动进度与 MKV 等扩展格式解码。")
                }
                .font(.footnote)
                .foregroundStyle(.secondary)
            }
            .navigationTitle("媒体来源")
            .toolbar {
                ToolbarItem(placement: .topBarTrailing) {
                    Button("完成") { showLibrary = false }
                }
            }
        }
    }

    private var urlSheet: some View {
        NavigationStack {
            Form {
                TextField("https://example.com/stream.m3u8", text: $inputURL)
                    .keyboardType(.URL)
                    .textInputAutocapitalization(.never)
                    .autocorrectionDisabled()
                Text("仅支持 AVPlayer 能够直接播放的 HTTPS MP4 / HLS 等媒体地址。")
                    .font(.footnote)
                    .foregroundStyle(.secondary)
            }
            .navigationTitle("网络播放")
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("取消") { showURLSheet = false }
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button("播放") {
                        let value = inputURL.trimmingCharacters(in: .whitespacesAndNewlines)
                        guard let url = URL(string: value),
                              url.scheme?.lowercased() == "https", url.host != nil else {
                            playbackError = "请输入有效的 HTTPS 视频地址。"
                            return
                        }
                        showURLSheet = false
                        load(url, title: url.lastPathComponent.isEmpty ? "网络影片" : url.lastPathComponent)
                    }
                }
            }
        }
    }

    private func openFile(_ url: URL) {
        scopedURL?.stopAccessingSecurityScopedResource()
        let access = url.startAccessingSecurityScopedResource()
        scopedURL = access ? url : nil
        load(url, title: url.lastPathComponent)
    }

    private func load(_ url: URL, title: String) {
        player.pause()
        player.replaceCurrentItem(with: AVPlayerItem(url: url))
        observedVideoSize = .zero
        currentTitle = title
        playing = true
        playbackRate = 1
        controlsVisible = true
        player.play()
    }

    private func togglePlayback() {
        guard player.currentItem != nil else { showLibrary = true; return }
        if playing { player.pause() } else { player.play(); player.rate = playbackRate }
        playing.toggle()
    }

    private func seek(by seconds: Double) {
        guard player.currentItem != nil else { return }
        let now = safeCurrentTime
        let duration = validDuration
        let goal = max(0, duration > 0 ? min(now + seconds, duration) : now + seconds)
        player.seek(to: CMTime(seconds: goal, preferredTimescale: 600))
    }
}

// Read UIWindow safe insets even when the artwork deliberately ignores them.
// Critical difference: VIDEO is edge-to-edge, CONTROLS avoid camera/status UI.
private struct SystemInsetsReader: UIViewRepresentable {
    @Binding var insets: UIEdgeInsets

    func makeUIView(context: Context) -> SystemInsetsView {
        let view = SystemInsetsView()
        view.onChange = { newValue in
            DispatchQueue.main.async {
                if insets != newValue { insets = newValue }
            }
        }
        return view
    }

    func updateUIView(_ view: SystemInsetsView, context: Context) {
        view.onChange = { newValue in
            DispatchQueue.main.async {
                if insets != newValue { insets = newValue }
            }
        }
        view.setNeedsLayout()
    }
}

private final class SystemInsetsView: UIView {
    var onChange: ((UIEdgeInsets) -> Void)?
    override init(frame: CGRect) {
        super.init(frame: frame)
        isUserInteractionEnabled = false
        backgroundColor = .clear
    }
    required init?(coder: NSCoder) {
        super.init(coder: coder)
        isUserInteractionEnabled = false
        backgroundColor = .clear
    }
    override func didMoveToWindow() {
        super.didMoveToWindow()
        report()
    }
    override func safeAreaInsetsDidChange() {
        super.safeAreaInsetsDidChange()
        report()
    }
    override func layoutSubviews() {
        super.layoutSubviews()
        report()
    }
    private var lastValue: UIEdgeInsets = .zero
    private func report() {
        guard let window = window else { return }
        let safe = window.safeAreaInsets
        if safe != lastValue {
            lastValue = safe
            onChange?(safe)
        }
    }
}

