// Available on iOS 27.1. The real fold rectangle is read from UIKit's
// reserved region API, instead of guessing its location from screen size.
@available(iOS 27.1, *)
private struct DuoFoldRegionReader: UIViewRepresentable {
    @Binding var region: CGRect?

    func makeUIView(context: Context) -> FoldTrackingView {
        let view = FoldTrackingView()
        view.onRegionChange = { candidate in
            if region != candidate { region = candidate }
        }
        return view
    }

    func updateUIView(_ view: FoldTrackingView, context: Context) {
        view.onRegionChange = { candidate in
            if region != candidate { region = candidate }
        }
        view.setNeedsLayout()
    }
