@available(iOS 27.1, *)
private final class FoldTrackingView: UIView {
    var onRegionChange: ((CGRect?) -> Void)?
    private var lastRegion: CGRect?

    override init(frame: CGRect) {
        super.init(frame: frame)
        isUserInteractionEnabled = false
        backgroundColor = .clear
    }

    required init?(coder: NSCoder) {
        super.init(coder: coder)
        isUserInteractionEnabled = false
        backgroundColor = .clear
    }

    override func layoutSubviews() {
        super.layoutSubviews()
        let candidate = reservedRegions(kind: .division)
            .first(where: { $0.isActive })?.frame
        if candidate != lastRegion {
            lastRegion = candidate
            DispatchQueue.main.async { [weak self] in
                self?.onRegionChange?(candidate)
            }
        }
    }
}

