// MARK: - WebDAV multi-mount library
// All WebDAV operations are read-only; credentials never go into UserDefaults.

private struct DAVMount: Identifiable, Codable, Equatable, Sendable {
    var id: UUID = UUID()
    var title: String
    var address: String
    var username: String

    var url: URL? { URL(string: address) }
    var keychainAccount: String { address + "|" + username }
}

private struct DAVEntry: Identifiable, Sendable {
    let url: URL
    let name: String
    let isFolder: Bool
    let byteSize: Int64?
    var id: String { url.absoluteString }
}

private enum DAVError: LocalizedError {
    case message(String)
    var errorDescription: String? {
        if case .message(let value) = self { return value }
        return nil
    }
}

private enum DAVAddress {
    static func normalize(_ input: String) -> URL? {
        let trimmed = input.trimmingCharacters(in: .whitespacesAndNewlines)
        guard var parts = URLComponents(string: trimmed),
              parts.scheme?.lowercased() == "https",
              let host = parts.host, !host.isEmpty,
              parts.user == nil, parts.password == nil,
              parts.query == nil, parts.fragment == nil else { return nil }
        // A WebDAV mount is a collection, so its URL needs a trailing slash.
        if !parts.percentEncodedPath.hasSuffix("/") { parts.percentEncodedPath += "/" }
        return parts.url
    }
}

private enum DAVSecrets {
    private static let service = "DuoCinema.WebDAV.v1"

    @discardableResult
    static func save(_ password: String, for account: String) -> Bool {
        let key: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: account
        ]
        SecItemDelete(key as CFDictionary)
        guard !password.isEmpty else { return true }
        var attrs = key
        attrs[kSecValueData as String] = Data(password.utf8)
        attrs[kSecAttrAccessible as String] = kSecAttrAccessibleAfterFirstUnlockThisDeviceOnly
        return SecItemAdd(attrs as CFDictionary, nil) == errSecSuccess
    }

    static func read(for account: String) -> String {
        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: account,
            kSecReturnData as String: true,
            kSecMatchLimit as String: kSecMatchLimitOne
        ]
        var result: CFTypeRef?
        guard SecItemCopyMatching(query as CFDictionary, &result) == errSecSuccess,
              let data = result as? Data else { return "" }
        return String(decoding: data, as: UTF8.self)
    }

    static func remove(for account: String) {
        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: account
        ]
        SecItemDelete(query as CFDictionary)
    }
}

// Reject cross-origin redirects, which must never receive a Basic Auth header.
private final class DAVRedirectProtector: NSObject, URLSessionTaskDelegate {
    let root: URL
    init(root: URL) { self.root = root }

    func urlSession(_ session: URLSession, task: URLSessionTask,
                    willPerformHTTPRedirection response: HTTPURLResponse,
                    newRequest request: URLRequest,
                    completionHandler: @escaping (URLRequest?) -> Void) {
        guard let target = request.url,
              target.scheme?.lowercased() == "https",
              target.host?.lowercased() == root.host?.lowercased(),
              (target.port ?? 443) == (root.port ?? 443),
              target.path.hasPrefix(root.path) else {
            completionHandler(nil)
            return
        }
        completionHandler(request)
    }
}

private final class DAVClient: @unchecked Sendable {
    let root: URL
    let username: String
    private let password: String
    private let protector: DAVRedirectProtector
    private let session: URLSession

    init(root: URL, username: String, password: String) {
        self.root = root
        self.username = username
        self.password = password
        self.protector = DAVRedirectProtector(root: root)
        let config = URLSessionConfiguration.ephemeral
        config.timeoutIntervalForRequest = 35
        config.timeoutIntervalForResource = 180
        config.httpShouldSetCookies = false
        config.httpCookieAcceptPolicy = .never
        self.session = URLSession(configuration: config, delegate: protector, delegateQueue: nil)
    }

    deinit { session.invalidateAndCancel() }

    private func request(_ url: URL, method: String) -> URLRequest {
        var result = URLRequest(url: url)
        result.httpMethod = method
        result.cachePolicy = .reloadIgnoringLocalCacheData
        if !username.isEmpty || !password.isEmpty {
            let credentials = Data("\(username):\(password)".utf8).base64EncodedString()
            result.setValue("Basic \(credentials)", forHTTPHeaderField: "Authorization")
        }
        return result
    }

    func list(_ folder: URL, completion: @escaping @Sendable (Result<[DAVEntry], Error>) -> Void) {
        var request = self.request(folder, method: "PROPFIND")
        request.setValue("1", forHTTPHeaderField: "Depth")
        request.setValue("application/xml; charset=utf-8", forHTTPHeaderField: "Content-Type")
        request.httpBody = Data("""
            <?xml version="1.0" encoding="utf-8"?>
            <d:propfind xmlns:d="DAV:"><d:prop><d:displayname/><d:resourcetype/><d:getcontentlength/></d:prop></d:propfind>
            """.utf8)
        session.dataTask(with: request) { [weak self] data, response, error in
            if let error { completion(.failure(error)); return }
            guard let response = response as? HTTPURLResponse else {
                completion(.failure(DAVError.message("没有收到服务器响应，请检查网络和 HTTPS 地址。")))
                return
            }
            guard response.statusCode == 207, let data else {
                let explanation: String
                switch response.statusCode {
                case 401: explanation = "认证失败：请检查账号、密码或应用专用密码。"
                case 403: explanation = "服务器拒绝访问该目录（403）。"
                case 404: explanation = "找不到 WebDAV 目录（404），请检查完整路径。"
                case 405, 501: explanation = "该地址不支持 WebDAV PROPFIND；可能填的是普通网页地址。"
                default: explanation = "WebDAV 目录读取失败，HTTP 状态码 \(response.statusCode)。"
                }
                completion(.failure(DAVError.message(explanation)))
                return
            }
            let parser = DAVXMLCollector()
            guard parser.parse(data), let self else {
                completion(.failure(DAVError.message("WebDAV 目录数据不是有效 XML。")))
                return
            }
            let rootPath = self.root.path
            let rootPrefix = rootPath.hasSuffix("/") ? rootPath : rootPath + "/"
            let folderPath = folder.path.trimmingCharacters(in: CharacterSet(charactersIn: "/"))
            let candidates: [DAVEntry] = parser.items.compactMap { record in
                guard let href = URL(string: record.href, relativeTo: folder)?.absoluteURL,
                      href.scheme?.lowercased() == "https",
                      href.host?.lowercased() == self.root.host?.lowercased(),
                      (href.port ?? 443) == (self.root.port ?? 443),
                      (href.path == rootPath || href.path.hasPrefix(rootPrefix)),
                      href.path.trimmingCharacters(in: CharacterSet(charactersIn: "/")) != folderPath else {
                    return nil
                }
                let name = record.displayName.isEmpty ? href.lastPathComponent : record.displayName
                return DAVEntry(url: href, name: name, isFolder: record.folder, byteSize: record.length)
            }
            // Only show known AVPlayer types; don't imply MKV/AVI decoding.
            let visible = candidates.filter { $0.isFolder || Self.isPlayable($0.name) }
            completion(.success(visible.sorted {
                if $0.isFolder != $1.isFolder { return $0.isFolder }
                return $0.name.localizedStandardCompare($1.name) == .orderedAscending
            }))
        }.resume()
    }

    static func isPlayable(_ filename: String) -> Bool {
        ["mp4", "m4v", "mov", "mp3", "m4a"].contains(URL(fileURLWithPath: filename).pathExtension.lowercased())
    }

    func download(_ entry: DAVEntry, progress: @escaping (Double, Int64, Int64) -> Void,
                  completion: @escaping (Result<URL, Error>) -> Void) -> DAVTransfer {
        let transfer = DAVTransfer(request: request(entry.url, method: "GET"), root: root,
                                   filename: entry.url.lastPathComponent,
                                   progress: progress, completion: completion)
        transfer.start()
        return transfer
    }
}

private struct DAVRecord {
    var href = ""
    var displayName = ""
    var folder = false
    var length: Int64?
}

private final class DAVXMLCollector: NSObject, XMLParserDelegate {
    private(set) var items: [DAVRecord] = []
    private var current: DAVRecord?
    private var targetField: String?
    private var buffer = ""

    func parse(_ data: Data) -> Bool {
        let parser = XMLParser(data: data)
        parser.delegate = self
        return parser.parse()
    }

    func parser(_ parser: XMLParser, didStartElement elementName: String,
                namespaceURI: String?, qualifiedName qName: String?,
                attributes attributeDict: [String: String]) {
        let tag = elementName.components(separatedBy: ":").last?.lowercased() ?? elementName.lowercased()
        if tag == "response" { current = DAVRecord() }
        if tag == "collection" { current?.folder = true }
        if ["href", "displayname", "getcontentlength"].contains(tag), current != nil {
            targetField = tag
            buffer = ""
        }
    }

    func parser(_ parser: XMLParser, foundCharacters string: String) {
        if targetField != nil { buffer += string }
    }

    func parser(_ parser: XMLParser, didEndElement elementName: String,
                namespaceURI: String?, qualifiedName qName: String?) {
        let tag = elementName.components(separatedBy: ":").last?.lowercased() ?? elementName.lowercased()
        if tag == targetField {
            let text = buffer.trimmingCharacters(in: .whitespacesAndNewlines)
            switch tag {
            case "href": current?.href = text
            case "displayname": current?.displayName = text
            case "getcontentlength": current?.length = Int64(text)
            default: break
            }
            targetField = nil
            buffer = ""
        }
        if tag == "response" {
            if let item = current, !item.href.isEmpty { items.append(item) }
            current = nil
        }
    }
}

// Moving the downloaded file in the delegate callback is essential: iOS
// discards URLSession's temporary download location after that callback.
// URLSession invokes delegate callbacks on its serial delegate queue. Its
// mutable bookkeeping stays on that queue; only UI progress is sent to main.
private final class DAVTransfer: NSObject, URLSessionDownloadDelegate, URLSessionTaskDelegate, @unchecked Sendable {
    private let request: URLRequest
    private let root: URL
    private let filename: String
    private let progressHandler: (Double, Int64, Int64) -> Void
    private let finishHandler: (Result<URL, Error>) -> Void
    private var storedURL: URL?
    private var storageError: Error?
    private var completed = false
    private var downloadTask: URLSessionDownloadTask?
    private lazy var session: URLSession = {
        let config = URLSessionConfiguration.ephemeral
        config.timeoutIntervalForResource = 3600
        config.httpShouldSetCookies = false
        config.httpCookieAcceptPolicy = .never
        return URLSession(configuration: config, delegate: self, delegateQueue: nil)
    }()

    init(request: URLRequest, root: URL, filename: String,
         progress: @escaping (Double, Int64, Int64) -> Void,
         completion: @escaping (Result<URL, Error>) -> Void) {
        self.request = request
        self.root = root
        self.filename = filename
        self.progressHandler = progress
        self.finishHandler = completion
    }

    func start() {
        downloadTask = session.downloadTask(with: request)
        downloadTask?.resume()
    }

    func cancel() { downloadTask?.cancel() }

    func urlSession(_ session: URLSession, task: URLSessionTask,
                    willPerformHTTPRedirection response: HTTPURLResponse,
                    newRequest request: URLRequest,
                    completionHandler: @escaping (URLRequest?) -> Void) {
        guard let target = request.url,
              target.scheme?.lowercased() == "https",
              target.host?.lowercased() == root.host?.lowercased(),
              (target.port ?? 443) == (root.port ?? 443),
              target.path.hasPrefix(root.path) else {
            completionHandler(nil)
            return
        }
        completionHandler(request)
    }

    func urlSession(_ session: URLSession, downloadTask: URLSessionDownloadTask,
                    didWriteData bytesWritten: Int64, totalBytesWritten: Int64,
                    totalBytesExpectedToWrite: Int64) {
        let value = totalBytesExpectedToWrite > 0
            ? Double(totalBytesWritten) / Double(totalBytesExpectedToWrite) : -1
        DispatchQueue.main.async {
            self.progressHandler(value, totalBytesWritten, totalBytesExpectedToWrite)
        }
    }

    func urlSession(_ session: URLSession, downloadTask: URLSessionDownloadTask,
                    didFinishDownloadingTo location: URL) {
        guard let response = downloadTask.response as? HTTPURLResponse,
              response.statusCode == 200 || response.statusCode == 206 else {
            storageError = DAVError.message("视频下载失败：服务器返回了无效的 HTTP 状态。")
            return
        }
        do {
            let dir = FileManager.default.urls(for: .cachesDirectory, in: .userDomainMask)[0]
                .appendingPathComponent("DuoCinema/WebDAV", isDirectory: true)
            try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
            let ext = URL(fileURLWithPath: filename).pathExtension.lowercased()
            let target = dir.appendingPathComponent(UUID().uuidString).appendingPathExtension(ext.isEmpty ? "mp4" : ext)
            try FileManager.default.moveItem(at: location, to: target)
            storedURL = target
        } catch { storageError = error }
    }

    func urlSession(_ session: URLSession, task: URLSessionTask,
                    didCompleteWithError error: Error?) {
        guard !completed else { return }
        completed = true
        let outcome: Result<URL, Error>
        if let error { outcome = .failure(error) }
        else if let storageError { outcome = .failure(storageError) }
        else if let storedURL { outcome = .success(storedURL) }
        else { outcome = .failure(DAVError.message("服务器没有返回可播放的文件。")) }
        DispatchQueue.main.async { self.finishHandler(outcome) }
        session.finishTasksAndInvalidate()
    }
}

@MainActor private final class DAVLibraryModel: ObservableObject {
    private static let storeKey = "DuoCinema.savedDAVMounts.v2"
    @Published private(set) var mounts: [DAVMount] = []
    @Published private(set) var activeMount: DAVMount?
    @Published var entries: [DAVEntry] = []
    @Published var folderTitle = ""
    @Published var connecting = false
    @Published var loading = false
    @Published var downloading = false
    @Published var downloadProgress = -1.0
    @Published var downloadedBytes: Int64 = 0
    @Published var totalBytes: Int64 = 0
    @Published var downloadingTitle = ""
    @Published var errorMessage: String?
    private var client: DAVClient?
    private var stack: [URL] = []
    private var transfer: DAVTransfer?
    private var transferID: UUID?
    private var browseSequence = UUID()

    var canGoBack: Bool { stack.count > 1 }

    init() {
        if let data = UserDefaults.standard.data(forKey: Self.storeKey),
           let decoded = try? JSONDecoder().decode([DAVMount].self, from: data) {
            mounts = decoded
        }
        // Migrate a valid single connection from V1.2–V1.6, retaining its
        // existing Keychain secret and never importing the plaintext password.
        if mounts.isEmpty,
           let oldAddress = UserDefaults.standard.string(forKey: "duocinema.dav.url"),
           let url = DAVAddress.normalize(oldAddress) {
            let username = UserDefaults.standard.string(forKey: "duocinema.dav.user") ?? ""
            mounts = [DAVMount(title: url.host ?? "WebDAV", address: url.absoluteString, username: username)]
            persist()
        }
    }

    func addAndConnect(title: String, address: String, username: String, password: String) {
        guard let url = DAVAddress.normalize(address) else {
            errorMessage = "请输入完整的 HTTPS WebDAV 目录地址，不要包含账号、密码或查询参数。"
            return
        }
        guard !connecting else { return }
        let normalizedUser = username.trimmingCharacters(in: .whitespacesAndNewlines)
        let display = title.trimmingCharacters(in: .whitespacesAndNewlines)
        let mount = DAVMount(title: display.isEmpty ? (url.host ?? "WebDAV") : display,
                             address: url.absoluteString, username: normalizedUser)
        let candidate = DAVClient(root: url, username: normalizedUser, password: password)
        connecting = true
        errorMessage = nil
        candidate.list(url) { [weak self] result in
            DispatchQueue.main.async {
                guard let self else { return }
                self.connecting = false
                switch result {
                case .success(let results):
                    let exists = self.mounts.first(where: { $0.address == mount.address && $0.username == mount.username })
                    if !DAVSecrets.save(password, for: mount.keychainAccount) {
                        self.errorMessage = "服务器已连接，但密码无法保存到系统钥匙串。请检查 App 签名与 Keychain 权限。"
                        return
                    }
                    var saved = mount
                    if let exists { saved.id = exists.id }
                    self.mounts.removeAll { $0.id == saved.id }
                    self.mounts.append(saved)
                    self.persist()
                    self.client = candidate
                    self.activeMount = saved
                    self.stack = [url]
                    self.folderTitle = saved.title
                    self.entries = results
                case .failure(let error):
                    self.errorMessage = error.localizedDescription
                }
            }
        }
    }

    func openMount(_ mount: DAVMount) {
        guard let root = mount.url, !connecting else { return }
        let secret = DAVSecrets.read(for: mount.keychainAccount)
        let nextClient = DAVClient(root: root, username: mount.username, password: secret)
        connecting = true
        errorMessage = nil
        nextClient.list(root) { [weak self] result in
            DispatchQueue.main.async {
                guard let self else { return }
                self.connecting = false
                switch result {
                case .success(let results):
                    self.client = nextClient
                    self.activeMount = mount
                    self.stack = [root]
                    self.entries = results
                    self.folderTitle = mount.title
                case .failure(let error):
                    self.errorMessage = error.localizedDescription
                }
            }
        }
    }

    func disconnect() {
        cancelDownload()
        browseSequence = UUID()
        activeMount = nil
        client = nil
        entries = []
        stack = []
        errorMessage = nil
    }

    func deleteMount(_ mount: DAVMount) {
        if activeMount?.id == mount.id { disconnect() }
        mounts.removeAll { $0.id == mount.id }
        DAVSecrets.remove(for: mount.keychainAccount)
        persist()
    }

    func select(_ entry: DAVEntry, onPlay: @escaping (URL, String) -> Void) {
        if entry.isFolder {
            stack.append(entry.url)
            loadFolder(entry.url)
            return
        }
        guard let client, !downloading else { return }
        errorMessage = nil
        downloading = true
        downloadingTitle = entry.name
        downloadProgress = -1
        downloadedBytes = 0
        totalBytes = 0
        let ticket = UUID()
        transferID = ticket
        transfer = client.download(entry, progress: { [weak self] fraction, received, expected in
            guard let self, self.transferID == ticket else { return }
            self.downloadProgress = fraction
            self.downloadedBytes = received
            self.totalBytes = expected
        }, completion: { [weak self] result in
            guard let self, self.transferID == ticket else { return }
            self.transfer = nil
            self.transferID = nil
            self.downloading = false
            switch result {
            case .success(let cached): onPlay(cached, entry.name)
            case .failure(let error):
                if (error as NSError).code != NSURLErrorCancelled { self.errorMessage = error.localizedDescription }
            }
        })
    }

    func cancelDownload() {
        transferID = nil
        transfer?.cancel()
        transfer = nil
        downloading = false
        downloadProgress = -1
    }

    func back() {
        guard stack.count > 1 else { return }
        stack.removeLast()
        if let folder = stack.last { loadFolder(folder) }
    }

    func refresh() {
        if let folder = stack.last { loadFolder(folder) }
    }

    private func loadFolder(_ folder: URL) {
        guard let client else { return }
        let sequence = UUID()
        browseSequence = sequence
        loading = true
        errorMessage = nil
        folderTitle = folder == stack.first ? (activeMount?.title ?? "WebDAV") : folder.lastPathComponent
        client.list(folder) { [weak self] result in
            DispatchQueue.main.async {
                guard let self, self.browseSequence == sequence else { return }
                self.loading = false
                switch result {
                case .success(let content): self.entries = content
                case .failure(let error): self.errorMessage = error.localizedDescription
                }
            }
        }
    }

    private func persist() {
        if let data = try? JSONEncoder().encode(mounts) {
            UserDefaults.standard.set(data, forKey: Self.storeKey)
        }
    }
}

private struct WebDAVLibraryView: View {
    let onPlay: (URL, String) -> Void
    @StateObject private var model = DAVLibraryModel()
    @State private var showingAdd = false
    @State private var search = ""
    @Environment(\.dismiss) private var dismiss

    private var visibleEntries: [DAVEntry] {
        if search.isEmpty { return model.entries }
        return model.entries.filter { $0.name.localizedCaseInsensitiveContains(search) }
    }

    var body: some View {
        NavigationStack {
            List {
                if model.activeMount == nil {
                    Section("已保存的云盘") {
                        if model.mounts.isEmpty {
                            ContentUnavailableView("还没有挂载云盘", systemImage: "externaldrive.badge.plus",
                                                   description: Text("先添加 WebDAV / NAS 连接。"))
                        }
                        ForEach(model.mounts) { mount in
                            Button { model.openMount(mount) } label: {
                                HStack(spacing: 12) {
                                    Image(systemName: "externaldrive.fill.badge.wifi")
                                        .foregroundStyle(.cyan)
                                        .frame(width: 28)
                                    VStack(alignment: .leading, spacing: 3) {
                                        Text(mount.title).foregroundStyle(.primary)
                                            .font(.body.weight(.medium))
                                        Text(mount.address)
                                            .font(.caption).foregroundStyle(.secondary)
                                            .lineLimit(1)
                                    }
                                    Spacer()
                                    Image(systemName: "chevron.right").foregroundStyle(.tertiary)
                                }
                            }
                            .disabled(model.connecting)
                            .swipeActions {
                                Button(role: .destructive) { model.deleteMount(mount) } label: {
                                    Label("删除挂载", systemImage: "trash")
                                }
                            }
                        }
                        if model.connecting { ProgressView("正在验证 WebDAV 连接…") }
                    }
                    Section {
                        Button { model.errorMessage = nil; showingAdd = true } label: {
                            Label("添加 WebDAV / NAS", systemImage: "plus.circle.fill")
                        }
                    }
                    Section("其他云盘") {
                        Label("iCloud Drive / 其他文件提供方：从播放器的“文件 App”进入",
                              systemImage: "icloud")
                        Label("SMB：可先在 iPhone 文件 App 的“连接服务器”中配置",
                              systemImage: "server.rack")
                    }
                    .font(.footnote).foregroundStyle(.secondary)
                } else {
                    Section {
                        HStack(spacing: 10) {
                            Image(systemName: "externaldrive.fill.badge.wifi")
                                .foregroundStyle(.cyan)
                            VStack(alignment: .leading) {
                                Text(model.activeMount?.title ?? "WebDAV")
                                    .font(.headline)
                                Text(model.folderTitle).font(.caption).foregroundStyle(.secondary)
                            }
                            Spacer()
                            if model.loading { ProgressView() }
                            Button { model.refresh() } label: {
                                Image(systemName: "arrow.clockwise")
                            }
                            .disabled(model.loading)
                            .accessibilityLabel("刷新文件夹")
                        }
                    }
                    Section("影片和文件夹") {
                        if !model.loading && visibleEntries.isEmpty {
                            Text(search.isEmpty ? "这个文件夹没有可播放的视频或子文件夹。" : "没有匹配的文件。")
                                .foregroundStyle(.secondary)
                        }
                        ForEach(visibleEntries) { item in
                            Button { model.select(item, onPlay: onPlay) } label: {
                                HStack(spacing: 12) {
                                    Image(systemName: item.isFolder ? "folder.fill" : "film")
                                        .foregroundStyle(item.isFolder ? .yellow : .cyan)
                                        .frame(width: 28)
                                    VStack(alignment: .leading, spacing: 3) {
                                        Text(item.name).foregroundStyle(.primary).lineLimit(2)
                                        if let byteSize = item.byteSize, byteSize > 0, !item.isFolder {
                                            Text(ByteCountFormatter.string(fromByteCount: byteSize, countStyle: .file))
                                                .font(.caption).foregroundStyle(.secondary)
                                        }
                                    }
                                    Spacer()
                                    Image(systemName: item.isFolder ? "chevron.right" : "play.circle")
                                        .foregroundStyle(.secondary)
                                }
                            }
                            .disabled(model.downloading || model.loading)
                        }
                    }
                    if model.downloading {
                        Section("下载后播放") {
                            Text(model.downloadingTitle).lineLimit(1)
                            if model.downloadProgress >= 0 {
                                ProgressView(value: min(1, max(0, model.downloadProgress)))
                            } else {
                                ProgressView()
                            }
                            HStack {
                                Text(ByteCountFormatter.string(fromByteCount: model.downloadedBytes, countStyle: .file))
                                Spacer()
                                if model.totalBytes > 0 {
                                    Text(ByteCountFormatter.string(fromByteCount: model.totalBytes, countStyle: .file))
                                } else {
                                    Text("大小未知")
                                }
                            }
                            .font(.caption).foregroundStyle(.secondary)
                            Button("取消下载", role: .destructive) { model.cancelDownload() }
                        }
                    }
                    Section {
                        Button { model.disconnect(); search = "" } label: {
                            Label("返回挂载列表", systemImage: "arrow.left.circle")
                        }
                    }
                }
                if let error = model.errorMessage {
                    Section("提示") {
                        Text(error).font(.footnote).foregroundStyle(.red)
                        Button("清除提示") { model.errorMessage = nil }
                    }
                }
                Section {
                    Text("WebDAV 使用 HTTPS 和密码钥匙串；此版本先缓存完整文件再播放，暂不支持远程拖动进度。只列出 AVPlayer 常见支持格式。")
                        .font(.caption).foregroundStyle(.secondary)
                }
            }
            .navigationTitle("我的云盘")
            .searchable(text: $search, prompt: "搜索当前文件夹")
            .toolbar {
                ToolbarItem(placement: .topBarLeading) {
                    if model.canGoBack {
                        Button { model.back(); search = "" } label: {
                            Label("上一级", systemImage: "chevron.left")
                        }
                    }
                }
                ToolbarItem(placement: .topBarTrailing) {
                    Button("完成") { model.cancelDownload(); dismiss() }
                }
            }
            .sheet(isPresented: $showingAdd) {
                DAVAddMountView(model: model)
            }
            .onChange(of: model.activeMount?.id) { _, value in
                if value != nil { showingAdd = false; search = "" }
            }
            .onDisappear { model.cancelDownload() }
        }
    }
}

private struct DAVAddMountView: View {
    @ObservedObject var model: DAVLibraryModel
    @Environment(\.dismiss) private var dismiss
    @State private var title = ""
    @State private var address = ""
    @State private var username = ""
    @State private var password = ""

    var body: some View {
        NavigationStack {
            Form {
                Section("挂载信息") {
                    TextField("名称（例如：家里的 NAS）", text: $title)
                    TextField("https://nas.example.com/dav/", text: $address)
                        .keyboardType(.URL)
                        .textInputAutocapitalization(.never)
                        .autocorrectionDisabled()
                    TextField("用户名", text: $username)
                        .textInputAutocapitalization(.never)
                    SecureField("密码 / 应用专用密码", text: $password)
                }
                Section {
                    Text("仅支持 HTTPS WebDAV。账号密码不会写入项目源码；保存到当前设备的系统钥匙串，连接成功后才加入挂载列表。")
                        .font(.footnote).foregroundStyle(.secondary)
                }
                if model.connecting {
                    Section { ProgressView("正在验证服务器…") }
                }
                if let error = model.errorMessage {
                    Section("连接失败") {
                        Text(error).foregroundStyle(.red).font(.footnote)
                    }
                }
            }
            .navigationTitle("添加云盘")
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("取消") { dismiss() }
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button("连接并保存") {
                        model.addAndConnect(title: title, address: address,
                                            username: username, password: password)
                    }
                    .disabled(model.connecting || address.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
                }
            }
        }
    }
}
